import{_ as t,o as d,c as o,a2 as c}from"./chunks/framework.CTeY_0bQ.js";const p=JSON.parse('{"title":"AgentRuntime：引擎对 agent 平台的要求","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"reference/contracts/agent-runtime.md","filePath":"reference/contracts/agent-runtime.md","lastUpdated":null}'),a={name:"reference/contracts/agent-runtime.md"};function r(i,e,n,l,s,u){return d(),o("div",null,[...e[0]||(e[0]=[c('<div><h1 id="agentruntime-引擎对-agent-平台的要求" tabindex="-1">AgentRuntime：引擎对 agent 平台的要求 <a class="header-anchor" href="#agentruntime-引擎对-agent-平台的要求" aria-label="Permalink to &quot;AgentRuntime：引擎对 agent 平台的要求&quot;">​</a></h1><p>引擎（<code>engine/src</code>）只通过 <code>AgentRuntime</code>（<code>engine/src/runtime.ts</code>）与 agent 平台打交道。现有的实现在各平台的适配器里：Paseo（<code>adapters/paseo/paseo-runtime.ts</code>）、DeepSeek Harness（<code>adapters/dsh/dsh-runtime.ts</code>）、摸高（<code>adapters/mogao/mogao-runtime.ts</code>）；测试用 <code>REQ_PIPELINE_FAKE_RUNTIME</code> 指向的假实现（<code>engine/test/fake-runtime.ts</code>）。要让 laoshi 运行在别的 agent 平台上，就是为那个平台写一个适配器和它的 <code>AgentRuntime</code>（见 <a href="./../design/adapter-guide">adapter-guide</a>）。</p><p>本文说明：每个方法属于哪一级、没有它时现在的行为、以及适配器应该怎么做。<code>runtime.ts</code> 里的类型和注释是字段定义的准确来源，本文不重复。</p><h2 id="级别" tabindex="-1">级别 <a class="header-anchor" href="#级别" aria-label="Permalink to &quot;级别&quot;">​</a></h2><ul><li><strong>必需</strong>：没有就不能运行流水线。适配器必须实现。</li><li><strong>可选</strong>：平台没有时返回 <code>null</code>（或抛出），引擎按&quot;现状&quot;一栏处理。</li><li><strong>按需</strong>：只有对应功能被使用时才会调用（卡片接单、需求总览、联合需求、<code>--worktree</code>）。</li></ul><p>&quot;现状&quot;一栏记录的是引擎今天的真实行为，不是理想行为。标了 ⚠ 的是降级不够平滑、适配器作者需要特别注意的地方。</p><h2 id="必需" tabindex="-1">必需 <a class="header-anchor" href="#必需" aria-label="Permalink to &quot;必需&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>要求</th><th>备注</th></tr></thead><tbody><tr><td><code>verifyOrigin(agentId, cwd)</code></td><td>确认发起流水线的会话存在，且工作目录是 <code>cwd</code>；不满足时抛出面向用户的原因</td><td>步骤 agent 要挂在发起会话下，平台给子 agent 的工作目录必须与会话一致（见 ADR 0001）。没有&quot;会话&quot;概念的平台，应在适配器里自行定义&quot;发起者&quot;并让此方法恒通过</td></tr><tr><td><code>startAgent(input)</code></td><td>按 <code>role</code>、<code>prompt</code>、<code>cwd</code>、<code>labels</code>、<code>profile</code> 创建一个步骤 agent；<code>parentAgentId</code> 非空时挂在该会话下；<code>workspaceId</code> 非空时放进该工作区</td><td>返回 <code>StepAgent</code></td></tr><tr><td><code>StepAgent.wait(timeoutMs)</code></td><td>等待当前回合结束，最多 <code>timeoutMs</code>；遇到权限请求时提前返回</td><td>返回值的 <code>status</code> 为 <code>idle</code> / <code>error</code> / <code>permission</code> / <code>timeout</code>；<code>usage</code> 平台不报告时为 <code>null</code></td></tr><tr><td><code>StepAgent.followUp(text)</code></td><td>在同一会话里开始新回合</td><td>用于&quot;结果文件缺失，请补写&quot;</td></tr><tr><td><code>StepAgent.archive()</code></td><td>归档该 agent</td><td></td></tr><tr><td><code>attachAgent(agentId)</code></td><td>接上一个之前（可能由另一个流水线进程）启动的 agent</td><td>续跑、重新接着等用</td></tr><tr><td><code>notifyAgent(agentId, text)</code></td><td>向已有会话投递一条消息，不打断它</td><td>进展、需要决定的问题、结论都靠它发回会话。⚠ 没有等价能力的平台，至少要写通知文件让使用者看到</td></tr><tr><td><code>interruptAgent(agentId, text)</code></td><td>打断当前回合，改为处理 <code>text</code></td><td>用于停止一个步骤</td></tr><tr><td><code>close()</code></td><td>释放连接</td><td></td></tr></tbody></table><h2 id="可选" tabindex="-1">可选 <a class="header-anchor" href="#可选" aria-label="Permalink to &quot;可选&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>平台没有时</th><th>现状</th></tr></thead><tbody><tr><td><code>listProfiles()</code>（req-kit 1.x 叫 <code>listPaseoProfiles</code>）</td><td>返回 <code>null</code></td><td>只影响用 <code>platformProfile</code>（旧名 <code>paseoProfile</code>）引用平台档案的配置：解析不了就拒绝启动并说明。只用 <code>provider/model</code> 直配时不调用</td></tr><tr><td><code>listServices(target)</code></td><td>返回 <code>null</code></td><td>流水线调用时都带 <code>.catch(() =&gt; null)</code>，<code>null</code> 表示&quot;不由平台管理服务&quot;，改用 <code>verify.md</code> 里的手工启动命令</td></tr><tr><td><code>startServices(target, names, timeoutMs)</code>、<code>stopServices(...)</code></td><td>—</td><td>只在 <code>listServices</code> 返回名字后才调用；失败时按启动失败报告给步骤</td></tr><tr><td><code>providerQuota(providers)</code></td><td>返回 <code>null</code></td><td>额度提醒关闭，不影响运行（<code>.catch(() =&gt; null)</code>）</td></tr><tr><td><code>recentActivity(agentId, limit)</code></td><td>返回 <code>null</code></td><td>查看进度时不附&quot;最近动作&quot;（<code>.catch(() =&gt; null)</code>）</td></tr><tr><td><code>runningTool(agentId)</code></td><td>返回 <code>null</code></td><td>关闭&quot;打断搜索大目录命令&quot;（1.13）（<code>.catch(() =&gt; null)</code>）</td></tr><tr><td><code>capabilities()</code></td><td>返回 <code>null</code></td><td>当作&quot;未知&quot;，不做依赖这些工具的假设（<code>.catch(() =&gt; null)</code>）</td></tr><tr><td><code>providerStatus()</code></td><td>返回 <code>null</code></td><td>只在接单器体检时用；<code>null</code> 不报问题</td></tr><tr><td><code>scheduleMessage(input)</code></td><td>返回 <code>null</code></td><td>⚠ 流水线内部（等待提醒、自动继续、定时检查、预约验证）拿到 <code>null</code> 就不预约；但 <code>launch.ts</code> 的&quot;预约开始&quot;在拿到 <code>null</code> 时<strong>直接失败</strong>并提示&quot;到时再启动&quot;。其他平台需要本机定时器或让使用者手动继续（见下文&quot;调度&quot;）</td></tr><tr><td><code>cancelSchedule(id)</code></td><td>—</td><td>下一次运行和暂停命令会调用它取消状态文件里记录的预约</td></tr></tbody></table><h2 id="按需" tabindex="-1">按需 <a class="header-anchor" href="#按需" aria-label="Permalink to &quot;按需&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>用在哪里</th><th>备注</th></tr></thead><tbody><tr><td><code>createWorktree(request)</code>、<code>waitForWorkspaceSetup(id, timeoutMs)</code></td><td><code>--worktree</code>（<code>worktree.ts</code>）和联合需求（<code>joint.ts</code>）</td><td>⚠ 创建失败是硬错误。没有平台工作区的适配器，可以在适配器内用 <code>git worktree</code> 实现并返回 <code>{ workspaceId, directory }</code>；<code>waitForWorkspaceSetup</code> 可恒返回 <code>{ status: &quot;none&quot; }</code></td></tr><tr><td><code>startSessionAgent(input)</code></td><td>从卡片接单（<code>card-cmd.ts</code>）：为需求新开一个顶层会话</td><td>没有则不能用接单器</td></tr><tr><td><code>scheduleNewAgent(input)</code></td><td>需求总览的定时发送（<code>digest.ts --schedule</code>）</td><td>返回 <code>null</code> 时该功能关闭</td></tr><tr><td><code>answerPermission(agentId, requestId, approve, reason)</code></td><td><code>laoshi permission &lt;需求&gt; approve|deny</code>（<code>permission-cmd.ts</code>）：平台的审批不能在它自己的界面里回答、由对话问人时，laoshi 转达人的决定；<code>requestId</code> 为 <code>null</code> 表示现在等待的那一个</td><td>没有时，审批按平台自己的方式处理（如 Paseo、dsh 的界面）</td></tr></tbody></table><p>适配器还可以声明 <code>runsInChat</code>（<code>PlatformAdapter</code>）：平台只在对话的一个轮次内保留对话的机器时，引擎不能在后台运行，<code>launch.ts</code> 让它在对话的命令里运行，给对话的消息（<code>notifyAgent</code>）写进 <code>chat.log</code> 并显示在命令输出里。状态文件记下运行引擎的机器（<code>host</code>），另一台机器上记录的进程不算还在运行。</p><h2 id="调度" tabindex="-1">调度 <a class="header-anchor" href="#调度" aria-label="Permalink to &quot;调度&quot;">​</a></h2><p>引擎里所有&quot;以后再做&quot;（预约开始、等待提醒、限流后自动继续、定时检查、预约验证）都表达为：<strong>在某个时间，向发起会话投递一条写明步骤的消息</strong>（ADR 0020）。适配器实现 <code>scheduleMessage</code> 时有三种选择：</p><ol><li>平台有等价的定时任务 → 直接映射（Paseo 的做法）。</li><li>平台没有 → 适配器自己保存计划，由一个常驻的本机进程到点调用 <code>notifyAgent</code>。</li><li>都做不到 → 返回 <code>null</code>，让引擎按上表&quot;现状&quot;处理。</li></ol><h2 id="一致性要求" tabindex="-1">一致性要求 <a class="header-anchor" href="#一致性要求" aria-label="Permalink to &quot;一致性要求&quot;">​</a></h2><p>新适配器至少应满足：</p><ul><li>通过 <code>engine/test</code> 中使用 <code>fake-runtime.ts</code> 的编排测试所覆盖的行为约定（步骤顺序、续跑、重新接着等、结果文件追问、打断）。读 <code>fake-runtime.ts</code> 可以看到引擎对每个方法的真实期望。</li><li><code>StepAgent.wait</code> 返回 <code>permission</code> 时，<code>pendingPermissions</code> 非空且有可读的 <code>title</code>。</li><li>步骤 agent 的创建要保证产物写在 <code>cwd</code> 下（ADR 0001 的问题：有的平台在传了 parent 时会改用 parent 的目录）。</li><li>不要让某个可选方法抛出未捕获的异常来表示&quot;不支持&quot;，除非上表标了 ⚠；用 <code>null</code>。</li></ul><h2 id="计划中的修订-adr-0008-提议" tabindex="-1">计划中的修订（ADR 0008，提议） <a class="header-anchor" href="#计划中的修订-adr-0008-提议" aria-label="Permalink to &quot;计划中的修订（ADR 0008，提议）&quot;">​</a></h2><p><a href="./../adr/0008-capability-sources-and-platform-plugin">ADR 0008</a> 定下了以下修订的方向，将与实现一起提交，本文暂不改动：能力标明来源（平台 / 插件 / 内置 / 降级）；新增&quot;回答待处理的请求&quot;与审批策略；<code>listPaseoProfiles</code> 改名为 <code>listProfiles</code>；<code>attachAgent</code> 改为&quot;恢复步骤会话&quot;；引入 agent 事件模型，由核心推导 <code>wait</code>、活动和用量；把对话相关的能力拆为&quot;对话通道&quot;。</p><h2 id="中性化-laoshi-m2a–m2e-已处理" tabindex="-1">中性化（laoshi M2a–M2e 已处理） <a class="header-anchor" href="#中性化-laoshi-m2a–m2e-已处理" aria-label="Permalink to &quot;中性化（laoshi M2a–M2e 已处理）&quot;">​</a></h2><p>req-kit 1.x 里带 Paseo 字样的地方，laoshi 中已改为中性的名称：</p><ul><li>方法与字段：<code>listPaseoProfiles</code> → <code>listProfiles</code>（M2a），<code>capabilities().paseoTools</code> → <code>platformTools</code>（M2e）。<code>ServiceTarget</code>、<code>ManagedService</code> 本来就是中性的名字，只改了注释。</li><li>状态文件字段：<code>originAgentId</code>、<code>worktree.workspaceId</code>、<code>schedules[]</code> 在第 2 版中改名（M2d，见 <code>state.md</code>）；对外契约不变。</li><li>面向使用者的文案和提示词：改用适配器的词汇表（M2e，<code>engine/src/words.ts</code>，见 <a href="./../design/platform-vocabulary">platform-vocabulary</a>）；<code>engine/prompts/paseo-services.md</code> 改名为 <code>managed-services.md</code>。</li><li>会话识别：由适配器声明环境变量（<code>originEnv</code>，M2a）；使用者识别同样由适配器声明（<code>userEnv</code>，如摸高的 <code>AIMAX_USER_NAME</code>，ADR 0007）。</li><li>配置：<code>AgentProfile.paseoProfile</code> → <code>platformProfile</code>，<code>paseoServices</code> → <code>platformServices</code>，旧名继续读取（M2e）；daemon 地址可写在 <code>platform.paseo</code> 中（M2c）。</li></ul><p><code>engine/test/platform.test.ts</code> 检查核心代码和提示词里不出现平台名（有意保留的旧字段名、对外契约字段，在那一行或上一行写明 <code>platform-name:</code> 和原因）。</p></div><p class="source-note">本页由仓库中的 <a href="https://github.com/yiyisf/laoshi/blob/main/contracts/agent-runtime.md">contracts/agent-runtime.md</a> 生成。<a href="https://github.com/yiyisf/laoshi/edit/main/contracts/agent-runtime.md">在 GitHub 上编辑</a></p>',2)])])}const g=t(a,[["render",r]]);export{p as __pageData,g as default};
